def-group:

    {{{ oval_metadata("The password minimum length should be set appropriately.", rule_title=rule_title) }}}
    {{% if product in [ 'slmicro6', 'sle15', 'sle16' ] %}}









    {{% else %}}



    {{% endif %}}


{{{
oval_param_in_file_variable_test(
    filepath=login_defs_path,
    parameter="PASS_MIN_LEN",
    pattern="^[\s]*(?i)(PASS_MIN_LEN[\s]+\d+)",
    regex_capture="PASS_MIN_LEN\s+(\d+)",
    operation="greater than or equal",
    type="int",
    test_id="test_pass_min_len",
    variable="var_accounts_password_minlen_login_defs"
)
}}}

{{% set login_defs_drop_in_config_dir = "/".join(login_defs_drop_in_path.split("/")[:-1]) %}}
{{{
oval_param_in_file_variable_test(
    filepath=login_defs_drop_in_config_dir,
    filename_regex=".*\.defs$",
    parameter="PASS_MIN_LEN",
    pattern="^[\s]*(?i)(PASS_MIN_LEN[\s]+\d+)",
    regex_capture="PASS_MIN_LEN\s+(\d+)",
    operation="greater than or equal",
    type="int",
    test_id="test_pass_min_len_logindefs_drop_in_path",
    variable="var_accounts_password_minlen_login_defs"
)
}}}






    {{{ login_defs_drop_in_config_dir }}}
    .*\.defs$
    ^\s*PASS_MIN_LEN\s*
    1
